// Obtener el mensaje principal
const message = items[0].json.body;

// Texto del mensaje
const content = message.content || "";

// Adjuntos
const attachments = message.attachments || [];

// Regex → generar URL interna
function makeInternal(url) {
  if (!url) return url;

  return url.replace(
    /^https:\/\/([a-zA-Z0-9\-]+)\.ocm\.aigentss\.cloud/,
    'http://$1.ocm.aigentss.cloud:3000'
  );
}

// ------------------------------------
// Procesar TODOS los attachments
// ------------------------------------
const processedAttachments = attachments.map(att => ({
  ...att,
  data_url_external: att.data_url || null,
  data_url_internal: makeInternal(att.data_url),
  thumb_url_external: att.thumb_url || null,
  thumb_url_internal: makeInternal(att.thumb_url)
}));

// ------------------------------------
// Detectar tipos presentes en el mensaje
// ------------------------------------
let type = "unknown";

// Caso: solo texto
if (attachments.length === 0 && content.trim() !== "") {
  type = "text";

// Caso: hay adjuntos
} else if (attachments.length > 0) {

  // Si TODOS son imágenes
  if (attachments.every(a => a.file_type === "image")) {
    type = content.trim() !== "" ? "image_with_text" : "image";
  }

  // Si TODOS son audios
  else if (attachments.every(a => a.file_type === "audio")) {
    type = "audio";

  // Si TODOS son location
  } else if (attachments.every(a => a.file_type === "location")) {
    type = "location";

  // Mezcla de adjuntos → híbrido
  } else {
    type = "mixed";
  }
}

return [
  {
    json: {
      type,
      content_text: content,
      attachments: processedAttachments,
      raw: items[0].json
    }
  }
];

const node = items[0].json;
const editFields = $('Edit Fields').item.json;

// Extraer coordenadas del attachment
const attachment = node.attachments?.[0] || {};
const lat = attachment.coordinates_lat || null;
const lon = attachment.coordinates_long || null;

// Construir el content_text para el siguiente nodo
//const content = {
//  lat,
//  lon
//};
const content = `${lat}, ${lon}`;

let result = {
  type: node.type,
  content: content,   // aquí va listo para el agente
  raw: editFields
};

return [{ json: result }];

const out = [];

for (const item of $input.all()) {
  const type = item.json.type;

  if (type === "text" || type === "image_with_text") {
    out.push({
      json: {
        content: item.json.content_text,
        type: "text"
      }
    });
  } else {
    out.push(item);
  }
}

return out;

const node = items[0].json;
const editFields = $('Edit Fields').item.json;

let result = {
  type: node.type,
  content_text: node.content,
  raw: editFields

};

return [{ json: result }];

const msgs = $json.output.messages || [];

return msgs.map((m, i) => ({
  indx: i,
  sms: m.sms || "",
  url: m.url || "",
  hasUrl: Boolean(m.url && m.url.trim() !== "")
}));

