const event = String($json.body?.event || '').toLowerCase();
const messageType = String($json.body?.message_type || '').toLowerCase();
const isPrivate = Boolean($json.body?.private);

const currentMessage = $json.body?.conversation?.messages?.find(
  msg => String(msg?.id) === String($json.body?.id)
);

const senderType = String(
  currentMessage?.sender_type || ''
).toLowerCase();

const isIncomingUserMessage =
  event === 'message_created' &&
  messageType === 'incoming' &&
  !isPrivate &&
  senderType === 'contact';

const isPublicHumanTakeoverMessage =
  event === 'message_created' &&
  messageType === 'outgoing' &&
  !isPrivate &&
  senderType === 'user';

const shouldContinue = isIncomingUserMessage || isPublicHumanTakeoverMessage;

return [{
  json: {
    ...$json,
    is_user_message: shouldContinue,
    _debug: {
      event,
      message_type: messageType,
      sender_type: senderType,
      private: isPrivate,
      matched_message_id: currentMessage?.id || null,
      incoming_user_message: isIncomingUserMessage,
      public_human_takeover_message: isPublicHumanTakeoverMessage,
    },
  },
}];

const concat = String($json.user_message_for_agent ?? $json.concat_message ?? '');
const content = `User Message: ${concat}`;

const memoryObj = {
  type: 'human',
  content,
  additional_kwargs: {},
  response_metadata: {},
};

return [{
  json: {
    ...$json,
    memory_message_obj: memoryObj,
    memory_message_text: JSON.stringify(memoryObj),
  },
}];

function stripAccents(s) {
  return String(s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function normalize(s) {
  return stripAccents(String(s || '').toLowerCase())
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const raw = $json.concat_message ?? '';
const msg = normalize(raw);

const negativePhrases = [
  'no acepto',
  'no autorizo',
  'no estoy de acuerdo',
  'no deseo continuar',
  'no quiero continuar',
  'me niego',
  'no doy permiso'
].map(normalize);

const negativeWords = [
  'rechazo',
  'deniego'
].map(normalize);

const isNegative =
  negativePhrases.some(p => (` ${msg} `).includes(` ${p} `)) ||
  negativeWords.some(w => msg.split(' ').includes(w));

const isEmpty = msg.length === 0;

return [{
  json: {
    ...$json,
    consent_eval: {
      raw,
      normalized: msg,
      is_negative: isNegative,
      is_empty: isEmpty,
      can_continue: !isNegative && !isEmpty
    }
  }
}];

const out = { ...$json };
const rawChannel = String($('Edit Fields').item.json.channel || '').toLowerCase();
const isWhatsapp = /whatsapp|waba/.test(rawChannel);
const tacNoticeSent = out.contact_context?.custom_attributes?.tac_notice_sent === true;

// Si este turno corresponde al primer TAC de WhatsApp y el notice aun no venia
// marcado en el contexto del item, dejamos que salga el Flow pero NO reingresamos
// al agente principal para evitar el doble mensaje.
if (isWhatsapp && !tacNoticeSent) {
  return [];
}

// Asegura existencia de la estructura
out.contact_context = out.contact_context || {};
out.contact_context.custom_attributes = out.contact_context.custom_attributes || {};

// Setea SOLO el atributo necesario
out.contact_context.custom_attributes.terms_accepted = true;
out.contact_context.custom_attributes.terms_accepted_at =
  out.contact_context.custom_attributes.terms_accepted_at ?? new Date().toISOString();
out.contact_context.tac = true;
out.contact_context.tac_accepted_at =
  out.contact_context.tac_accepted_at ?? new Date().toISOString();

return [{ json: out }];

const rawMessage = String($json.concat_message || '').trim();
const conversation = $json.conversation || {};
const mcpState = $json.mcp_booking_state || {};
const resolved = $json.intent_resolver || {};
const flow = $json.parsed_flow || {};
const isWhatsapp = /whatsapp|waba/.test(String($('Edit Fields').item.json.channel || '').toLowerCase());

function assignIf(target, key, value) {
  if (value === undefined || value === null || value === '' || value === '-') return;
  target[key] = value;
}

function compact(obj) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return obj;
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    if (v === undefined) continue;
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      const nested = compact(v);
      if (Object.keys(nested).length) out[k] = nested;
    } else if (!(v === null || v === '')) {
      out[k] = v;
    }
  }
  return out;
}

const previousBookingIntent = String(mcpState.booking_intent || conversation.custom_attributes?.booking_intent || 'fallback');
const bookingIntent = String(resolved.intent || previousBookingIntent || 'fallback');
const conversationAttrs = conversation.custom_attributes || {};
const selectedModel = resolved.selected_model || null;
const selectedModelId = resolved.selected_model_id ?? null;
const selectedEstablishmentName = resolved.selected_establishment_name || null;
const selectedEstablishmentId = resolved.selected_establishment_id ?? null;
const selectedZone = resolved.selected_zone || conversationAttrs.selected_zone || mcpState.selected_zone || null;
const selectedDate = resolved.selected_date || null;
const selectedTime = resolved.selected_time || null;
const purchaseTimeframeDays = resolved.purchase_timeframe_days ?? null;
const reviewedModels = resolved.reviewed_models || [];
const reviewedModelIds = resolved.reviewed_model_ids || [];
const missingFields = resolved.missing_fields || [];
const leadType = resolved.lead_type || null;
const autocomGroup = resolved.autocom_group || null;
const brandFamily = resolved.brand_family || null;
const commercialSubtype = resolved.commercial_subtype || null;
const searchMode = resolved.search_mode || null;

let bookingPhase = String(mcpState.booking_phase || conversation.custom_attributes?.booking_phase || 'unknown');
if (!bookingPhase || bookingPhase === 'unknown' || bookingPhase === 'fallback') {
  if (!resolved.has_personal_contact_data) bookingPhase = 'collect_personal';
  else if (!(selectedModel || selectedModelId)) bookingPhase = 'collect_model';
  else if (!resolved.lead_enrichment_completed) bookingPhase = 'collect_enrichment';
  else if (!selectedEstablishmentId) bookingPhase = 'collect_establishment';
  else if (!(selectedDate && selectedTime)) bookingPhase = 'collect_schedule';
  else bookingPhase = 'ready_to_book';
}

let route = 'agent_default';
if (resolved.discovery_route) route = resolved.discovery_route;
else if (resolved.should_send_personal_flow) route = 'send_personal_flow';
else if (resolved.wants_carousel) route = 'send_carousel';
else if (resolved.should_send_search_prompt) route = 'send_search_prompt';
else if (resolved.should_send_enrichment_flow) route = 'send_enrichment_flow';
else if (resolved.should_request_location) route = 'send_location_request';
else if (resolved.should_resolve_establishment) route = 'resolve_establishment_options';
else if (resolved.should_send_phase6_flow) route = 'send_phase6_flow';
else if (resolved.ready_to_book) route = 'booking_execute';
else if (flow.is_flow_payload) route = 'flow_payload';

const conversationUpdatePayload = {};
assignIf(conversationUpdatePayload, 'booking_intent', bookingIntent);
assignIf(conversationUpdatePayload, 'booking_phase', bookingPhase);
assignIf(conversationUpdatePayload, 'selected_city', resolved.effective_contact?.city);
assignIf(conversationUpdatePayload, 'selected_model', selectedModel);
assignIf(conversationUpdatePayload, 'selected_model_id', selectedModelId);
assignIf(conversationUpdatePayload, 'latest_selected_model', selectedModel);
assignIf(conversationUpdatePayload, 'latest_selected_model_id', selectedModelId);
assignIf(conversationUpdatePayload, 'selected_establishment_name', selectedEstablishmentName);
assignIf(conversationUpdatePayload, 'selected_establishment_id', selectedEstablishmentId);
assignIf(conversationUpdatePayload, 'selected_zone', selectedZone);
assignIf(conversationUpdatePayload, 'selected_date', selectedDate);
assignIf(conversationUpdatePayload, 'selected_time', selectedTime);
assignIf(conversationUpdatePayload, 'purchase_timeframe_days', purchaseTimeframeDays);
assignIf(conversationUpdatePayload, 'customer_name', resolved.effective_contact?.name);
assignIf(conversationUpdatePayload, 'customer_email', resolved.effective_contact?.email);
assignIf(conversationUpdatePayload, 'customer_identifier', resolved.effective_contact?.identifier);
assignIf(conversationUpdatePayload, 'customer_phone', resolved.effective_contact?.phone_number);
assignIf(conversationUpdatePayload, 'lead_type', leadType);
assignIf(conversationUpdatePayload, 'autocom_group', autocomGroup);
assignIf(conversationUpdatePayload, 'brand_family', brandFamily);
assignIf(conversationUpdatePayload, 'commercial_subtype', commercialSubtype);
assignIf(conversationUpdatePayload, 'search_mode', searchMode);
conversationUpdatePayload.booking_personal_data_complete = Boolean(resolved.has_personal_contact_data || resolved.personal_complete);
conversationUpdatePayload.lead_enrichment_status = resolved.lead_enrichment_completed ? 'completed' : (selectedModel ? 'in_progress' : 'not_started');

if (reviewedModels.length) conversationUpdatePayload.reviewed_models = reviewedModels;
if (reviewedModelIds.length) conversationUpdatePayload.reviewed_model_ids = reviewedModelIds;

if (resolved.lead_enrichment_payload) {
  conversationUpdatePayload.lead_enrichment = resolved.lead_enrichment_payload;
  conversationUpdatePayload.pending_intent = 'enriquecimiento_completado';
  conversationUpdatePayload.pending_intent_resolved = true;
  conversationUpdatePayload.pending_intent_summary = 'Enriquecimiento completado';
}

if (selectedEstablishmentId) {
  conversationUpdatePayload.establishment_question_pending = false;
  conversationUpdatePayload.establishment_prompt_type = '';
  conversationUpdatePayload.establishment_prompt_hash = '';
  conversationUpdatePayload.establishment_prompt_repeat_count = 0;
  conversationUpdatePayload.establishment_candidate_options = [];
}

if (resolved.has_location) {
  conversationUpdatePayload.selected_location_lat = resolved.selected_location_lat;
  conversationUpdatePayload.selected_location_lng = resolved.selected_location_lng;
  conversationUpdatePayload.booking_location_received_at = new Date().toISOString();
  conversationUpdatePayload.booking_location_request_pending = false;
}

if (route === 'send_location_request') {
  conversationUpdatePayload.booking_location_request_sent_at = new Date().toISOString();
  conversationUpdatePayload.booking_location_request_pending = true;
}

if (route === 'send_personal_flow' || route === 'send_enrichment_flow' || route === 'send_phase6_flow') {
  conversationUpdatePayload.booking_flow_sent_type = route;
  conversationUpdatePayload.booking_flow_sent_at = new Date().toISOString();
}

const canonicalConversationUpdate = compact({
  journey: {
    intent: bookingIntent,
    phase: bookingPhase,
    status: route === 'booking_execute' ? 'active' : 'waiting_user',
    updated_at: new Date().toISOString(),
  },
  selection: {
    search_mode: searchMode || undefined,
    lead_type: leadType || undefined,
    commercial_subtype: commercialSubtype || undefined,
    autocom_group: autocomGroup || undefined,
    brand_family: brandFamily || undefined,
    model_name: selectedModel || undefined,
    model_id: selectedModelId ?? undefined,
    reviewed_model_names: reviewedModels.length ? reviewedModels : undefined,
    reviewed_model_ids: reviewedModelIds.length ? reviewedModelIds : undefined,
  },
  enrichment: {
    status: resolved.lead_enrichment_completed ? 'completed' : (selectedModel ? 'in_progress' : 'not_started'),
    sent_at: ['send_enrichment_flow'].includes(route) ? new Date().toISOString() : undefined,
    payload: resolved.lead_enrichment_payload || undefined,
    completed_at: resolved.lead_enrichment_payload ? new Date().toISOString() : undefined,
  },
  establishment: {
    city: resolved.effective_contact?.city || undefined,
    zone: selectedZone || undefined,
    selected_name: selectedEstablishmentName || undefined,
    selected_id: selectedEstablishmentId ?? undefined,
    status: selectedEstablishmentId ? 'selected' : (route === 'send_establishment_candidate_list' || route === 'send_establishment_zone_list' || route === 'resolve_establishment_options' ? 'choosing' : undefined),
    location: resolved.has_location ? { lat: resolved.selected_location_lat, lng: resolved.selected_location_lng } : undefined,
  },
  schedule: {
    date: selectedDate || undefined,
    time: selectedTime || undefined,
    service_name: conversationUpdatePayload.selected_service || undefined,
    service_id: conversationUpdatePayload.selected_service_id || undefined,
    purchase_timeframe_days: purchaseTimeframeDays ?? undefined,
    appointment_id: conversationUpdatePayload.active_appointment_id || undefined,
    status: route === 'booking_execute' ? 'ready' : ((selectedDate || selectedTime) ? 'choosing' : undefined),
  },
  prompt_memory: {
    flow_type: ['send_personal_flow','send_enrichment_flow','send_phase6_flow'].includes(route) ? route : undefined,
    flow_status: ['send_personal_flow','send_enrichment_flow','send_phase6_flow'].includes(route) ? 'sent' : undefined,
    sent_at: ['send_personal_flow','send_enrichment_flow','send_phase6_flow'].includes(route) ? new Date().toISOString() : undefined,
    bound_phase: bookingPhase,
    bound_model_id: selectedModelId ?? undefined,
    bound_establishment_id: selectedEstablishmentId ?? undefined,
  },
  lead_enrichment: resolved.lead_enrichment_payload || undefined,
});
Object.assign(conversationUpdatePayload, canonicalConversationUpdate);

const contactUpdatePayload = flow.is_flow_payload ? {
  name: resolved.effective_contact?.name || undefined,
  email: resolved.effective_contact?.email || undefined,
  phone_number: resolved.effective_contact?.phone_number || undefined,
  identifier: resolved.effective_contact?.identifier || undefined,
  custom_attributes: {
    city: resolved.effective_contact?.city || undefined,
    identifier: resolved.effective_contact?.identifier || undefined,
    flow_token: flow.flow_token || undefined,
  },
} : {};

const stateSummaryForAgent = [
  'Current booking intent: ' + bookingIntent,
  'Current booking phase: ' + bookingPhase,
  'Latest selected model: ' + (selectedModel || '-'),
  'Lead type: ' + (leadType || '-'),
  'Autocom group: ' + (autocomGroup || '-'),
  'Selected establishment: ' + (selectedEstablishmentName || '-'),
  'Missing fields: ' + (missingFields.length ? missingFields.join(', ') : 'none'),
].join('\n');

const userMessageForAgent = [stateSummaryForAgent, 'Latest user message: ' + rawMessage].join('\n');

return [{
  json: {
    ...$json,
    user_message_for_agent: userMessageForAgent,
    booking_state: {
      route,
      booking_intent: bookingIntent,
      booking_phase: bookingPhase,
      is_whatsapp: isWhatsapp,
      personal_complete: Boolean(resolved.personal_complete),
      has_personal_contact_data: Boolean(resolved.has_personal_contact_data),
      lead_enrichment_completed: Boolean(resolved.lead_enrichment_completed),
      selected_model: selectedModel,
      selected_model_id: selectedModelId,
      reviewed_models: reviewedModels,
      reviewed_model_ids: reviewedModelIds,
      selected_establishment_name: selectedEstablishmentName,
      selected_establishment_id: selectedEstablishmentId,
      selected_zone: selectedZone,
      selected_location_lat: resolved.selected_location_lat ?? null,
      selected_location_lng: resolved.selected_location_lng ?? null,
      has_location: Boolean(resolved.has_location),
      needs_location_request: Boolean(resolved.should_request_location),
      missing_fields: missingFields,
      selected_date: selectedDate,
      selected_time: selectedTime,
      purchase_timeframe_days: purchaseTimeframeDays,
      effective_contact: resolved.effective_contact || {},
      lead_type: leadType,
      autocom_group: autocomGroup,
      brand_family: brandFamily,
      commercial_subtype: commercialSubtype,
      search_mode: searchMode,
    },
    router: {
      route,
      wants_carousel: Boolean(resolved.wants_carousel),
      carousel_segment: resolved.carousel_filters?.segment || 'all',
      carousel_mode: 'base',
      carousel_filters: resolved.carousel_filters || {},
