function pickFirst(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '' && String(value).trim() !== '-') {
      return String(value).trim();
    }
  }
  return '';
}

function toNumberIfPossible(value) {
  if (value === undefined || value === null || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function titleCase(value) {
  return String(value || '').toLowerCase().replace(/\b\w/g, (m) => m.toUpperCase()).trim();
}

function normalizeSlug(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function humanizeSlug(value) {
  return String(value || '').replace(/_/g, ' ').replace(/\s+/g, ' ').trim().toUpperCase();
}

function isLikelyGeneratedWidgetName(name) {
  const value = String(name || '').trim();
  if (!value) return true;
  if (/^[A-Za-z]+-[A-Za-z]+-\d{2,}$/i.test(value)) return true;
  if (/\d/.test(value) && /-/.test(value)) return true;
  if (/^(user|visitor|guest|anon|anonymous)[-_ ]?\d*$/i.test(value)) return true;
  return false;
}

function parseStructuredText(text) {
  const parsed = {};
  for (const line of String(text || '').split(/\r?\n/).map((l) => l.trim()).filter(Boolean)) {
    const match = line.match(/^([a-zA-Z0-9_ ]+):\s*(.+)$/);
    if (!match) continue;
    parsed[match[1].trim().toLowerCase().replace(/\s+/g, '_')] = match[2].trim();
  }
  return parsed;
}

function parseFlowPayload(text) {
  const parsed = parseStructuredText(text);
  const hasSignal =
    parsed.flow_token ||
    parsed.p1_medio_contacto ||
    parsed.p2_tiempo_compra ||
    ((parsed.name || parsed.email || parsed.identifier || parsed.city) && Object.keys(parsed).length >= 3);
  return {
    is_flow_payload: Boolean(hasSignal),
    is_basic_data_payload: Boolean(parsed.name || parsed.email || parsed.identifier || parsed.city || parsed.intent),
    is_enrichment_payload: Boolean(parsed.p1_medio_contacto || parsed.p2_tiempo_compra || parsed.p6_cotizacion || parsed.p7_comentario),
    is_phase6_payload: Boolean(parsed.preferred_date || parsed.preferred_time),
    name: pickFirst(parsed.name, parsed.nombre),
    identifier: pickFirst(parsed.identifier, parsed.cedula, parsed.cédula),
    email: pickFirst(parsed.email, parsed.correo),
    city: titleCase(pickFirst(parsed.city, parsed.ciudad)),
    phone_number: pickFirst(parsed.phone_number, parsed.numero, parsed.telefono, parsed.teléfono),
    flow_token: pickFirst(parsed.flow_token),
    intent: pickFirst(parsed.intent, parsed.asunto, parsed.subject),
    comments: pickFirst(parsed.comments, parsed.comentarios),
    preferred_date: pickFirst(parsed.preferred_date, parsed.fecha_visita, parsed.selected_date),
    preferred_time: pickFirst(parsed.preferred_time, parsed.horario_preferido, parsed.selected_time),
    purchase_timeframe_days: pickFirst(parsed.purchase_timeframe_days, parsed.purchase_timeframe, parsed.tiempo_compra),
    selected_model: pickFirst(parsed.selected_model, parsed.modelos_interes, parsed.modelo),
    selected_model_id: pickFirst(parsed.selected_model_id, parsed.product_id),
    selected_establishment_name: pickFirst(parsed.selected_establishment_name, parsed.selected_establishment, parsed.concesionario, parsed.establishment),
    selected_establishment_id: pickFirst(parsed.selected_establishment_id, parsed.establishment_id),
    lead_type: pickFirst(parsed.lead_type, parsed.tipo_lead),
    p1_medio_contacto: pickFirst(parsed.p1_medio_contacto),
    p2_tiempo_compra: pickFirst(parsed.p2_tiempo_compra),
    p3_test_drive: pickFirst(parsed.p3_test_drive),
    p4_forma_pago: pickFirst(parsed.p4_forma_pago),
    p5_competencia: pickFirst(parsed.p5_competencia),
    p5_competencia_detalle: pickFirst(parsed.p5_competencia_detalle),
    p6_cotizacion: pickFirst(parsed.p6_cotizacion),
    p7_comentario: pickFirst(parsed.p7_comentario),
    raw: parsed,
  };
}

function parseButtonReply(text) {
  const parsed = parseStructuredText(text);
  const payload = pickFirst(parsed.button_payload);
  const buttonText = pickFirst(parsed.button_text);
  const normalizedText = normalizeSlug(buttonText);
  const inferredAction = pickFirst(
    parsed.button_action,
    normalizedText.includes('mas_info') ? 'info' : '',
    normalizedText.includes('conocelo') || normalizedText.includes('prueba') || normalizedText.includes('persona') ? 'in_person' : ''
  );
  const inferredModel = pickFirst(
    parsed.model,
    payload && !payload.startsWith('search__') && !payload.startsWith('type__') && !payload.startsWith('brand__') && !payload.startsWith('commercial__') ? humanizeSlug(payload.replace(/_(info|persona|prueba)$/i, '')) : ''
  );
  return {
    is_button_reply: Boolean(parsed.button_action || payload),
    action: inferredAction,
    model: inferredModel,
    button_payload: payload,
    button_text: buttonText,
  };
}

function scanInteractiveReply(value) {
  if (!value || typeof value !== 'object') return null;
  if (typeof value.id === 'string' || typeof value.title === 'string') {
    return {
      id: pickFirst(value.id),
      title: pickFirst(value.title),
      description: pickFirst(value.description),
    };
  }
  for (const key of Object.keys(value)) {
    const nested = scanInteractiveReply(value[key]);
    if (nested) return nested;
  }
  return null;
}

function parseInteractiveReply(message, text) {
  const contentAttrs = message?.content_attributes || {};
  const additionalAttrs = message?.additional_attributes || {};
  const direct = scanInteractiveReply(contentAttrs) || scanInteractiveReply(additionalAttrs);
  return {
    id: pickFirst(direct?.id, contentAttrs.list_reply_id, additionalAttrs.list_reply_id),
    title: pickFirst(direct?.title),
    description: pickFirst(direct?.description),
    raw_text: String(text || '').trim(),
  };
}

function parseLocation(text) {
  const match = String(text || '').trim().match(/^(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)$/);
  if (!match) return null;
  return { lat: Number(match[1]), lng: Number(match[2]) };
}

function inferPurchaseDays(text, flowDays) {
  if (flowDays && /^\d+$/.test(String(flowDays))) return Number(flowDays);
  const msg = String(text || '').toLowerCase();
  if (/7\s*d[ií]as|esta\s+semana|pr[oó]ximos\s+7\s*d[ií]as/.test(msg)) return 7;
  if (/2\s*semanas|dos\s+semanas|15\s*d[ií]as/.test(msg)) return 15;
  if (/1\s*mes|un\s+mes|30\s*d[ií]as/.test(msg)) return 30;
  if (/evaluando|m[aá]s\s+adelante|sin\s+fecha|cotizando/.test(msg)) return 60;
  return toNumberIfPossible(mcpState.purchase_timeframe_days ?? canonicalSchedule.purchase_timeframe_days ?? conversationAttrs.purchase_timeframe_days);
}

function mapEnrichmentTimeframe(value) {
  const normalized = normalizeSlug(value);
  if (normalized === 'inmediato') return 7;
  if (normalized === 'uno_tres_meses') return 30;
  if (normalized === 'tres_seis_meses') return 90;
  if (normalized === 'solo_explorando') return 120;
  return null;
}

function uniqueStrings(values) {
  const seen = new Set();
  const out = [];
  for (const value of values || []) {
    const str = String(value || '').trim();
    if (!str) continue;
    const key = str.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(str);
  }
  return out;
}

function uniqueInts(values) {
  const seen = new Set();
  const out = [];
  for (const value of values || []) {
    const n = toNumberIfPossible(value);
    if (n === null || seen.has(n)) continue;
    seen.add(n);
    out.push(n);
  }
  return out;
}

function inferLeadTypeFromGroup(group, name, previousLeadType) {
  const normalizedGroup = normalizeSlug(group);
  const normalizedName = normalizeSlug(name);
  if (normalizedGroup === 'jac_camiones' || normalizedGroup === 'karry') return 'comercial';
  if (normalizedGroup === 'jetour' || normalizedGroup === 'jac_electrical') return 'particular';
  if (normalizedGroup === 'jac_nonelectric') {
    if (normalizedName.includes('taxi') || normalizedName.includes('servicio_especial')) return 'comercial';
    return previousLeadType || 'particular';
  }
  return previousLeadType || 'particular';
}

function parseSelection(interactiveReply, buttonReply) {
  const id = String(interactiveReply.id || buttonReply.button_payload || '').trim();
  if (!id) return { kind: '' };
  if (id === 'search__brand') return { kind: 'search_mode', search_mode: 'brand', route: 'send_brand_selector' };
  if (id === 'search__type') return { kind: 'search_mode', search_mode: 'type', route: 'send_type_selector' };
  if (id === 'type__particular') return { kind: 'lead_type', lead_type: 'particular', route: 'send_carousel', search_mode: 'type' };
  if (id === 'type__comercial') return { kind: 'lead_type', lead_type: 'comercial', route: 'send_commercial_selector', search_mode: 'type' };
  if (id === 'commercial__taxi') return { kind: 'commercial_subtype', commercial_subtype: 'taxi', lead_type: 'comercial', autocom_group: 'jac_nonelectric', query: 'taxi', route: 'send_carousel', search_mode: 'type' };
  if (id === 'commercial__servicio_especial') return { kind: 'commercial_subtype', commercial_subtype: 'servicio_especial', lead_type: 'comercial', autocom_group: 'jac_nonelectric', query: 'servicio', route: 'send_carousel', search_mode: 'type' };
  if (id === 'commercial__camiones') return { kind: 'commercial_subtype', commercial_subtype: 'camiones', lead_type: 'comercial', autocom_group: 'jac_camiones', route: 'send_carousel', search_mode: 'type' };
  if (id === 'commercial__minitruck') return { kind: 'commercial_subtype', commercial_subtype: 'minitruck', lead_type: 'comercial', autocom_group: 'karry', route: 'send_carousel', search_mode: 'type' };
  if (id.startsWith('brand__')) {
    const brand = id.slice(7);
    const map = {
      jac: { brand_key: 'jac_motors', query: 'jac' },
      jac_electricos: { autocom_group: 'jac_electrical', brand_family: 'jac_electricos' },
      jac_camiones: { autocom_group: 'jac_camiones', brand_family: 'jac_camiones' },
      jetour: { autocom_group: 'jetour', brand_family: 'jetour' },
      karry: { autocom_group: 'karry', brand_family: 'karry' },
    };
    return { kind: 'brand', route: 'send_carousel', search_mode: 'brand', ...(map[brand] || {}) };
  }
  if (id.startsWith('model__')) {
    const parts = id.split('__');
    if (parts.length >= 6) {
      return {
        kind: 'model_action',
        selected_model_id: toNumberIfPossible(parts[1]),
        autocom_group: parts[2],
        lead_type: parts[3],
        selected_model: humanizeSlug(parts[4]),
        action: parts[5],
      };
    }
  }
  return { kind: '' };
}

