const selectedModelId = $json.selected_model_id || bookingState.selected_model_id || $('Intent Resolver').item.json.intent_resolver?.selected_model_id || '';
const selectedEstablishmentName = $json.selected_establishment_name || bookingState.selected_establishment_name || $('Intent Resolver').item.json.intent_resolver?.selected_establishment_name || '';
