const baseConversationUpdatePayload = { ...($('Conversation Router').item.json.conversation_update_payload || {}), ...($json.conversation_update_payload || {}) };
const now = new Date().toISOString();
function safeNodeJson(name){ try { return $(name).item.json || {}; } catch { return {}; } }
