function normalize(value){ return String(value || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, ''); }
function clampText(value, max){ return String(value || '').trim().slice(0, max); }
const wabaContext = safeNodeJson('WABA Autocom1');
const fallbackSourceNumberPhone = $('Edit Fields').item.json.body?.conversation?.contact_inbox?.source_id || $('Webhook').item.json.body?.conversation?.contact_inbox?.source_id || '';
const isEarlyPersonalFlow = Boolean($json.force_personal_flow_after_tac || $('Intent Resolver').item.json.intent_resolver?.should_send_early_personal_flow);
const personalHeader = isEarlyPersonalFlow ? 'Atencion personalizada' : 'Datos personales';
const personalBody = isEarlyPersonalFlow ? '¡Hola! 👋 es un gusto saludarte. Para brindarte el mejor servicio por favor completa el siguiente formulario. Al continuar con esta conversacion, aceptas nuestros terminos: https://bit.ly/418l9x2' : 'Para continuar con tu solicitud, por favor comparte tus datos.';
