})) : [];

const hasCarouselGroupFilter = Object.prototype.hasOwnProperty.call(carouselFilters, 'autocom_group');
const hasCarouselLeadFilter = Object.prototype.hasOwnProperty.call(carouselFilters, 'lead_type');
const hasCarouselBrandFilter = Object.prototype.hasOwnProperty.call(carouselFilters, 'brand_family');
const normalizedGroupFilter = normalize(hasCarouselGroupFilter ? carouselFilters.autocom_group : autocomGroup);
const normalizedLeadFilter = normalize(hasCarouselLeadFilter ? carouselFilters.lead_type : leadType);
const normalizedBrandFilter = normalize(hasCarouselBrandFilter ? carouselFilters.brand_family : '');
const normalizedBrandKey = normalize(carouselFilters.brand_key || '');
const normalizedQueryFilter = normalize(carouselFilters.query || '');

const catalogFromMcp = rawCatalogFromMcp.filter((item) => {
  const itemGroup = normalize(item.autocom_group);
  const itemLead = normalize(item.lead_type);
  const itemBrand = normalize(item.brand_family);
  const itemTitle = normalize(item.title);
  if (normalizedBrandKey === 'jac_motors' && !['jac_nonelectric', 'jac_camiones'].includes(itemGroup)) return false;
  if (normalizedGroupFilter && itemGroup && itemGroup !== normalizedGroupFilter) return false;
  if (normalizedLeadFilter && itemLead && itemLead !== normalizedLeadFilter) return false;
  if (normalizedBrandFilter && itemBrand && itemBrand !== normalizedBrandFilter) return false;
  if (normalizedQueryFilter && !itemTitle.includes(normalizedQueryFilter)) return false;
  return true;
});

