}

function buildCatalogOutput(catalog, noteLabel, updateExtras = {}) {
  if (catalog.length === 0) {
    return {
      metaPayload: { messaging_product: 'whatsapp', recipient_type: 'individual', to: metaContext.source_number_phone, type: 'text', text: { body: 'No encontre modelos disponibles con ese filtro en este momento.' } },
      internalNote: 'Se envio carrusel dinamico sin resultados' + (noteLabel ? ' (' + noteLabel + ')' : '') + '.',
      conversationUpdatePayload: { ...baseConversationUpdatePayload, ...updateExtras },
    };
  }

  if (catalog.length === 1) {
    const item = catalog[0];
    const modelSlug = slugify(item.title || item.id || 'modelo');
    const groupSlug = slugify(item.autocom_group || autocomGroup || 'autocom');
    const leadSlug = slugify(item.lead_type || leadType || 'particular');
    const modelTitle = String(item.title || 'Modelo disponible').trim();
    const bodyLines = [modelTitle];
    if (item.year) bodyLines.push('Ano: ' + item.year);
    if (item.price) bodyLines.push('Desde: ' + item.price);
    bodyLines.push('Desea conocerlo en persona?');
    return {
      metaPayload: {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: metaContext.source_number_phone,
        type: 'interactive',
        interactive: {
          type: 'button',
          header: { type: 'text', text: modelTitle },
          body: { text: bodyLines.join('\n') },
          footer: { text: 'Autocom Colombia' },
          action: {
            buttons: [
              { type: 'reply', reply: { id: 'model__' + item.id + '__' + groupSlug + '__' + leadSlug + '__' + modelSlug + '__info', title: 'Mas info' } },
              { type: 'reply', reply: { id: 'model__' + item.id + '__' + groupSlug + '__' + leadSlug + '__' + modelSlug + '__in_person', title: 'Ver en persona' } },
            ],
          },
        },
      },
      internalNote: 'Se envio ficha interactiva de un solo modelo filtrado' + (noteLabel ? ' (' + noteLabel + ')' : '') + ': [' + [modelTitle].join(', ') + ']',
      conversationUpdatePayload: {
        ...baseConversationUpdatePayload,
        booking_last_catalog_sent_at: now,
        booking_last_catalog_mode: 'single_card',
        autocom_group: autocomGroup || undefined,
        lead_type: leadType || undefined,
        ...updateExtras,
      },
    };
  }

  const sentModelTitles = catalog.slice(0, 10).map((item) => String(item.title || item.id || 'Modelo sin nombre').trim());
  const cards = catalog.slice(0, 10).map((item, index) => {
    const modelSlug = slugify(item.title || item.id || 'modelo');
    const groupSlug = slugify(item.autocom_group || autocomGroup || 'autocom');
    const leadSlug = slugify(item.lead_type || leadType || 'particular');
    return {
      card_index: index,
      type: 'cta_url',
      header: { type: 'image', image: { link: item.image } },
      body: { text: item.title + '\nAño: ' + item.year + '\nDesde: ' + item.price },
      action: {
        buttons: [
          { type: 'quick_reply', quick_reply: { id: 'model__' + item.id + '__' + groupSlug + '__' + leadSlug + '__' + modelSlug + '__info', title: 'Mas info' } },
          { type: 'quick_reply', quick_reply: { id: 'model__' + item.id + '__' + groupSlug + '__' + leadSlug + '__' + modelSlug + '__in_person', title: 'Ver en persona' } },
        ],
      },
    };
  });
  const bodyText = noteLabel
    ? 'Estos son algunos modelos disponibles de ' + noteLabel + '.'
    : (autocomGroup ? 'Estos son algunos modelos disponibles segun el filtro que seleccionaste.' : 'Estos son algunos modelos Autocom disponibles.');
  return {
    metaPayload: { messaging_product: 'whatsapp', recipient_type: 'individual', to: metaContext.source_number_phone, type: 'interactive', interactive: { type: 'carousel', body: { text: bodyText }, action: { cards } } },
    internalNote: 'Se envio carrusel dinamico de modelos filtrados' + (noteLabel ? ' (' + noteLabel + ')' : '') + ': [' + sentModelTitles.join(', ') + ']',
    conversationUpdatePayload: {
      ...baseConversationUpdatePayload,
      booking_last_catalog_sent_at: now,
      booking_last_catalog_mode: 'quick_reply',
      autocom_group: autocomGroup || undefined,
      lead_type: leadType || undefined,
      ...updateExtras,
    },
  };
}

